import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);

  // ============ GESTION CAMÉRA ============
  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false
        });
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
      } catch (err) {
        setError('Impossible d\'accéder à la caméra');
      }
    };

    startCamera();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    };
  }, []);

  // ============ BOUCLE DE CAPTURE (FIXED) ============
  useEffect(() => {
    // Si on arrête le mode auto, on nettoie l'intervalle immédiatement
    if (!autoMode) {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      return;
    }

    captureIntervalRef.current = setInterval(async () => {
      if (!videoRef.current || isProcessingRef.current || videoRef.current.readyState < 2) return;

      try {
        isProcessingRef.current = true;

        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);
        setFrameCount(prev => prev + 1);

        // ✅ FIX CRITIQUE : Envoi de l'objet JSON avec la clé attendue
        const response = await attendanceAPI.recognize({ image_base64: imageBase64 });
        const data = response?.data;

        if (data?.success && data?.student) {
          setResult({
            success: true,
            name: data.student,
            email: data.email || 'N/A',
            confidence: (data.confidence * 100).toFixed(1),
            attendanceId: data.attendance_id,
            timestamp: new Date().toLocaleTimeString(),
            message: `✅ ${data.student} enregistré!`
          });
          setLastDetection(new Date().toLocaleTimeString());

          // Pause pour éviter les doublons
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 3000);
        }
      } catch (err) {
        console.warn('⚠️ Scan en cours...');
      } finally {
        isProcessingRef.current = false;
      }
    }, 800); // ⏱️ 800ms est plus stable pour laisser le temps au backend de répondre

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    };
  }, [autoMode]);

  // ============ CAPTURE MANUELLE (FIXED) ============
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setError(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);
      const imageBase64 = canvas.toDataURL('image/jpeg', 0.92);

      // ✅ FIX : Envoi en objet JSON
      const response = await attendanceAPI.recognize({ image_base64: imageBase64 });
      const data = response?.data;

      if (data.success) {
        setResult({
          success: true,
          name: data.student,
          email: data.email,
          confidence: (data.confidence * 100).toFixed(1),
          timestamp: new Date().toLocaleTimeString(),
          message: `✅ ${data.student} reconnu!`
        });
      } else {
        setError(data.message || 'Visage non reconnu');
      }
    } catch (err) {
      setError('Erreur lors de la communication avec le serveur');
    } finally {
      setLoading(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    setAutoMode(false);
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>👤 Pointage Automatique</h1>

      <div style={styles.videoContainer}>
        <video ref={videoRef} autoPlay playsInline muted style={styles.video} />
        <div style={{ ...styles.statusBadge, background: autoMode ? '#10B981' : '#6B7280' }}>
          {autoMode ? '🔄 Analyse...' : '⏸️ Pause'}
        </div>
        <div style={styles.frameCounter}>Analyse n° {frameCount}</div>
      </div>

      <div style={styles.actions}>
        <button onClick={handleManualCapture} disabled={loading} style={styles.btnCapture}>
           {loading ? 'Traitement...' : '📸 Scanner Maintenant'}
        </button>
        <button onClick={() => setAutoMode(!autoMode)} style={styles.btnToggle}>
           {autoMode ? 'Désactiver Auto' : 'Activer Auto'}
        </button>
        <button onClick={stopCamera} style={styles.btnStop}>🛑 Éteindre</button>
      </div>

      {result && (
        <div style={{ ...styles.resultBox, borderLeft: result.success ? '5px solid #10B981' : '5px solid #EF4444' }}>
          <h3>{result.message || result.name}</h3>
          <p>Confiance : {result.confidence}% | Heure : {result.timestamp}</p>
        </div>
      )}

      {error && <div style={styles.errorBox}>❌ {error}</div>}
    </div>
  );
};

const styles = {
  container: { padding: '20px', maxWidth: '800px', margin: '0 auto', fontFamily: 'sans-serif' },
  title: { textAlign: 'center', color: '#1F2937' },
  videoContainer: { position: 'relative', borderRadius: '12px', overflow: 'hidden', background: '#000' },
  video: { width: '100%', display: 'block' },
  statusBadge: { position: 'absolute', top: '10px', right: '10px', padding: '5px 12px', borderRadius: '20px', color: '#fff', fontSize: '12px', fontWeight: 'bold' },
  frameCounter: { position: 'absolute', bottom: '10px', left: '10px', color: '#fff', fontSize: '12px', background: 'rgba(0,0,0,0.5)', padding: '2px 8px', borderRadius: '4px' },
  actions: { display: 'flex', gap: '10px', margin: '20px 0' },
  btnCapture: { flex: 2, padding: '12px', background: '#10B981', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' },
  btnToggle: { flex: 1, padding: '12px', background: '#6366F1', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' },
  btnStop: { flex: 1, padding: '12px', background: '#EF4444', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' },
  resultBox: { padding: '15px', background: '#F3F4F6', borderRadius: '8px' },
  errorBox: { padding: '15px', background: '#FEE2E2', color: '#991B1B', borderRadius: '8px', marginTop: '10px' }
};

export default CameraRecognition;
